// -----------------------------------------------------------------------------
// Snippet 1: idl/file.idl (Header Doc) — Example 1
// -----------------------------------------------------------------------------
async function example_1() {
  // --- Blob / File Example ------------------------------------------------
    const blob = new Blob([bytes], { type: 'image/png' });
    const png  = await blob.arrayBuffer();
}

// -----------------------------------------------------------------------------
// Snippet 2: idl/file.idl (Header Doc) — Example 2
// -----------------------------------------------------------------------------
async function example_2() {
  // --- FileReader Example -------------------------------------------------
    function readModel(file) {
      return new Promise((resolve, reject) => {
        const r = new FileReader();
        r.onload  = () => resolve(r.result);
        r.onerror = () => reject(r.error);
        r.readAsArrayBuffer(file);
      });
    }
}

// -----------------------------------------------------------------------------
// Snippet 3: idl/file.idl (Header Doc) — Example 3
// -----------------------------------------------------------------------------
async function example_3() {
  // --- Object URLs Example ------------------------------------------------
    // Resolve a model's texture that only exists in memory.
    const url = URL.createObjectURL(textureFile);
    new THREE.TextureLoader().load(url, tex => {
      material.map = tex;
      URL.revokeObjectURL(url);
    });
}

// -----------------------------------------------------------------------------
// Snippet 4: idl/file.idl (Header Doc) — Example 4
// -----------------------------------------------------------------------------
async function example_4() {
  // --- Dropped Files Example ----------------------------------------------
    document.addEventListener('drop', async (event) => {
      event.preventDefault();
      if (event.dataTransfer.types[0] !== 'Files') return;
      for (const file of event.dataTransfer.files) {
        const text = await file.text();          // or a FileReader
        console.log(file.name, file.size, 'from', file.path, text.length);
      }
    });
    document.addEventListener('dragover', e => e.preventDefault());
}

// -----------------------------------------------------------------------------
// Snippet 5: idl/file.idl (Header Doc) — Example 5
// -----------------------------------------------------------------------------
async function example_5() {
  // --- Input File Example -------------------------------------------------
    // The standard hidden-input pattern.
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.addEventListener('change', () => useTexture(input.files[0]));
    myButton.onclick = () => input.click();
}

// -----------------------------------------------------------------------------
// Snippet 6: idl/file.idl (Header Doc) — Example 6
// -----------------------------------------------------------------------------
async function example_6() {
  // --- Downloading Example (<a download>) ---------------------------------
    function exportScene(text) {
      const url = URL.createObjectURL(new Blob([text], { type: 'text/plain' }));
      const link = document.createElement('a');
      link.href = url;
      link.download = 'scene.json';
      link.click();
      URL.revokeObjectURL(url);
    }
}

// -----------------------------------------------------------------------------
// Snippet 7: idl/file.idl (Header Doc) — Example 7
// -----------------------------------------------------------------------------
async function example_7() {
  // --- Dragging inside page (DataTransfer) --------------------------------
    row.draggable = true;
    row.addEventListener('dragstart', e => e.dataTransfer.setData('text/plain', row.id));
    list.addEventListener('dragover',  e => e.preventDefault());   // required
    list.addEventListener('drop', e => {
      e.preventDefault();
      const moved = document.getElementById(e.dataTransfer.getData('text/plain'));
      const before = e.offsetY < e.target.clientHeight / 2;
      e.target.parentNode.insertBefore(moved, before ? e.target : e.target.nextSibling);
    });
}

// -----------------------------------------------------------------------------
// Snippet 8: idl/noise.idl (Header Doc) — Example 1
// -----------------------------------------------------------------------------
async function example_8() {
  // --- Terrain heightmap with FBm -----------------------------------------
    const terrainSrc = FastNoise.create("Simplex");
    const terrain = FastNoise.create("FractalFBm");
    terrain.set("Source", terrainSrc);
    terrain.set("Octaves", 6);
    terrain.set("Gain", 0.5);
    terrain.set("Lacunarity", 2.0);
    const heightmap = terrain.genUniformGrid2D(0, 0, 512, 512, 0.002, 1337);
    // heightmap is a Float32Array with 262144 values
}

// -----------------------------------------------------------------------------
// Snippet 9: idl/noise.idl (Header Doc) — Example 2
// -----------------------------------------------------------------------------
async function example_9() {
  // --- Ridged mountains blended with plains -------------------------------
    const plains = FastNoise.create("FractalFBm");
    plains.set("Source", FastNoise.create("Simplex"));
    plains.set("Octaves", 4);
  
    const mountains = FastNoise.create("FractalRidged");
    mountains.set("Source", FastNoise.create("Perlin"));
    mountains.set("Octaves", 5);
  
    const biomeNoise = FastNoise.create("Simplex");
  
    const blended = FastNoise.create("Fade");
    blended.set("A", plains);
    blended.set("B", mountains);
    blended.set("Fade", biomeNoise);       // biome noise drives the blend
    blended.set("Interpolation", "Hermite");
  
    const world = blended.genUniformGrid2D(0, 0, 1024, 1024, 0.001, 42);
}

// -----------------------------------------------------------------------------
// Snippet 10: idl/noise.idl (Header Doc) — Example 3
// -----------------------------------------------------------------------------
async function example_10() {
  // --- 3D voxel density field for caves -----------------------------------
    const caveShape = FastNoise.create("FractalRidged");
    caveShape.set("Source", FastNoise.create("Perlin"));
    caveShape.set("Octaves", 3);
    caveShape.set("Gain", 0.6);
  
    const warped = FastNoise.create("DomainWarpGradient");
    warped.set("Source", caveShape);
    warped.set("Warp Amplitude", 30.0);
  
    const density = warped.genUniformGrid3D(0, 0, 0, 64, 64, 64, 0.02, 7);
    // density[z * 64*64 + y * 64 + x], negative = solid, positive = air
}

// -----------------------------------------------------------------------------
// Snippet 11: idl/noise.idl (Header Doc) — Example 4
// -----------------------------------------------------------------------------
async function example_11() {
  // --- Domain warp fractal for organic terrain ----------------------------
    const dwGrad = FastNoise.create("DomainWarpGradient");
    dwGrad.set("Source", FastNoise.create("Simplex"));
    dwGrad.set("Warp Amplitude", 20.0);
  
    const dwFrac = FastNoise.create("DomainWarpFractalProgressive");
    dwFrac.set("Domain Warp Source", dwGrad);
    dwFrac.set("Octaves", 4);
    dwFrac.set("Gain", 0.6);
  
    const organic = dwFrac.genUniformGrid2D(0, 0, 256, 256, 0.005, 99);
}

